// Colour pipeline vs colour-science references (testdata/golden/color, generated by
// tools/golden/generate.py): transfer functions, RGB matrices and display transforms,
// max |error| <= 1e-4.
#include <cmath>
#include <cstdint>
#include <string>
#include <vector>

#include "golden_assert.h"
#include "lineover/color.h"
#include "lo_test.h"
#include "npy_io.h"

using namespace lo::testing;
namespace color = lo::color;

namespace {

constexpr float kMaxError = 1e-4f;

float maxError(const ImageF32& actual, const ImageF32& expected) {
    float worst = 0.0f;
    for (std::size_t i = 0; i < actual.data.size(); ++i) worst = std::max(worst, std::fabs(actual.data[i] - expected.data[i]));
    return worst;
}

void checkClose(const ImageF32& actual, const std::string& expectedFile) {
    const ImageF32 expected = readNpyF32(goldenPath(expectedFile));
    LO_CHECK(actual.sameShape(expected));
    if (!actual.sameShape(expected)) return;
    const float worst = maxError(actual, expected);
    if (!(worst <= kMaxError)) std::cerr << "  " << expectedFile << ": max |error| " << worst << "\n";
    LO_CHECK(worst <= kMaxError);
}

ImageF32 mapPixels(const ImageF32& input, float (*f)(float)) {
    ImageF32 out = input;
    for (std::size_t i = 0; i < out.data.size(); ++i) {
        if (i % 4 != 3) out.data[i] = f(input.data[i]);
    }
    return out;
}

ImageF32 applyMatrix(const ImageF32& input, const color::Mat3& m) {
    ImageF32 out = input;
    color::applyMatrix(m, input.data.data(), out.data.data(), input.data.size() / 4);
    return out;
}

}  // namespace

LO_TEST(srgb_transfer_functions_match_colour_science) {
    const ImageF32 encoded = readNpyF32(goldenPath("color/encoded_f32.npy"));
    checkClose(mapPixels(encoded, color::srgbEotf), "color/srgb_eotf_f32.npy");
    checkClose(mapPixels(encoded, color::srgbOetf), "color/srgb_oetf_f32.npy");
}

LO_TEST(transfer_functions_round_trip_and_extend_symmetrically) {
    for (float v = -2.0f; v <= 4.0f; v += 0.01f) {
        LO_CHECK(std::fabs(color::srgbEotf(color::srgbOetf(v)) - v) <= 1e-5f * std::max(1.0f, std::fabs(v)));
    }
    LO_CHECK(color::srgbEotf(-0.5f) == -color::srgbEotf(0.5f));
}

LO_TEST(rgb_matrices_match_colour_science_including_out_of_range_values) {
    const ImageF32 linear = readNpyF32(goldenPath("color/linear_f32.npy"));
    checkClose(applyMatrix(linear, color::kSrgbToRec2020), "color/srgb_to_rec2020_f32.npy");
    checkClose(applyMatrix(linear, color::kRec2020ToSrgb), "color/rec2020_to_srgb_f32.npy");
    checkClose(applyMatrix(linear, color::kP3ToRec2020), "color/p3_to_rec2020_f32.npy");
    checkClose(applyMatrix(linear, color::kRec2020ToP3), "color/rec2020_to_p3_f32.npy");
}

// colour-science builds sRGB from the published (rounded) IEC 61966-2-1 matrix, not from
// the primaries, so the two directions are inverse only to ~3e-5: within the 1e-4 bound.
LO_TEST(matrices_are_inverse_pairs) {
    auto product = [](const color::Mat3& a, const color::Mat3& b) {
        color::Mat3 p{};
        for (int r = 0; r < 3; ++r)
            for (int c = 0; c < 3; ++c)
                for (int k = 0; k < 3; ++k) p.m[3 * r + c] += a.m[3 * r + k] * b.m[3 * k + c];
        return p;
    };
    for (const auto& pair : {product(color::kSrgbToRec2020, color::kRec2020ToSrgb), product(color::kP3ToRec2020, color::kRec2020ToP3)}) {
        for (int i = 0; i < 9; ++i) LO_CHECK(std::fabs(pair.m[i] - (i % 4 == 0 ? 1.0f : 0.0f)) < kMaxError);
    }
}

LO_TEST(srgb8_decode_matches_the_python_working_space) {
    // sRGB-encoded 8-bit -> linear Rec.2020, against reference.srgb8_to_working.
    const ImageF32 as01 = readNpyF32(goldenPath("input/pattern_rgba8_as_f32.npy"));
    std::vector<std::uint8_t> rgba8(as01.data.size());
    for (std::size_t i = 0; i < rgba8.size(); ++i) rgba8[i] = static_cast<std::uint8_t>(std::lround(as01.data[i] * 255.0f));
    ImageF32 out = as01;
    color::srgb8ToWorking(rgba8.data(), out.data.data(), rgba8.size() / 4);
    checkClose(out, "input/pattern_rec2020_f32.npy");
}

LO_TEST(display_transforms_match_colour_science) {
    const ImageF32 working = readNpyF32(goldenPath("input/pattern_rec2020_f32.npy"));
    ImageF32 srgb = working;
    color::workingToDisplay(working.data.data(), srgb.data.data(), working.data.size() / 4, color::Display::Srgb);
    checkClose(srgb, "color/working_to_srgb_display_f32.npy");
    ImageF32 p3 = working;
    color::workingToDisplay(working.data.data(), p3.data.data(), working.data.size() / 4, color::Display::DisplayP3);
    checkClose(p3, "color/working_to_p3_display_f32.npy");
}

LO_TEST(srgb8_round_trips_through_the_working_space) {
    // 8-bit sRGB -> working -> 8-bit sRGB is lossless (no gamma applied twice).
    std::vector<std::uint8_t> in(256 * 4), out(256 * 4);
    for (int i = 0; i < 256; ++i) in[4 * i] = in[4 * i + 1] = in[4 * i + 2] = in[4 * i + 3] = static_cast<std::uint8_t>(i);
    std::vector<float> working(256 * 4);
    color::srgb8ToWorking(in.data(), working.data(), 256);
    color::workingToDisplay8(working.data(), out.data(), 256, color::Display::Srgb);
    LO_CHECK(in == out);
}

LO_TEST(p3_source_reaches_p3_display_unchanged) {
    std::vector<std::uint8_t> in = {255, 0, 0, 255, 0, 255, 0, 255, 12, 200, 99, 128};
    std::vector<float> working(in.size());
    std::vector<std::uint8_t> out(in.size());
    color::p38ToWorking(in.data(), working.data(), 3);
    color::workingToDisplay8(working.data(), out.data(), 3, color::Display::DisplayP3);
    for (std::size_t i = 0; i < in.size(); ++i) LO_CHECK(std::abs(int(in[i]) - int(out[i])) <= 1);
}

LO_TEST(half_float_conversion_is_exact_for_representable_values) {
    for (std::uint32_t h = 0; h < 0x10000; ++h) {
        const auto half = static_cast<std::uint16_t>(h);
        const float f = color::halfToFloat(half);
        if (std::isnan(f)) {
            LO_CHECK(std::isnan(color::halfToFloat(color::floatToHalf(f))));
            continue;
        }
        LO_CHECK(color::floatToHalf(f) == half);
    }
    LO_CHECK(color::floatToHalf(65520.0f) == 0x7C00);  // rounds to +Inf
    LO_CHECK(color::halfToFloat(color::floatToHalf(0.1f)) == 0.0999755859375f);
}

LO_TEST(linear_extended_srgb_half_decodes_wide_gamut_values) {
    // Pure Display-P3 red as LINEAR_EXTENDED_SRGB has a negative green and blue.
    const float p3Red[4] = {1.0f, 0.0f, 0.0f, 1.0f};
    float linearSrgb[4];
    float viaP3[4];
    color::applyMatrix(color::kP3ToRec2020, p3Red, viaP3, 1);
    color::applyMatrix(color::kRec2020ToSrgb, viaP3, linearSrgb, 1);
    std::uint16_t halves[4];
    for (int c = 0; c < 4; ++c) halves[c] = color::floatToHalf(linearSrgb[c]);
    float working[4];
    color::linearExtendedSrgbHalfToWorking(halves, working, 1);
    for (int c = 0; c < 3; ++c) LO_CHECK(std::fabs(working[c] - viaP3[c]) < 2e-3f);
}

int main() { return runAllTests(); }
